display.text:
/**
 * Copyright (c) Facebook, Inc. and its affiliates.
 *
 * This source code is licensed under the MIT license found in the
 * LICENSE file in the root directory of this source tree.
 */

import {execSync, type ExecSyncOptionsWithStringEncoding} from 'child_process';
import path from 'path';
import query from 'querystring';
import _ from 'lodash';
import detect from 'detect-port';
import prompts from 'prompts';
import logger from '@docusaurus/logger';
import {matchRoutes as reactRouterMatchRoutes} from 'react-router-config';
import {
  parseURLPath,
  serializeURLPath,
  flattenRoutes,
  DEFAULT_PARSE_FRONT_MATTER,
  DEFAULT_STATIC_DIR_NAME,
  DEFAULT_I18N_DIR_NAME,
  DEFAULT_PORT,
  docuHash,
  simpleHash,
  escapePath,
  generate,
  type URLPath,
} from '@docusaurus/utils';
import {
  addTrailingSlash,
  addLeadingSlash,
  removeTrailingSlash,
  applyTrailingSlash,
  type ApplyTrailingSlashParams,
} from '@docusaurus/utils-common';
import {Joi, printWarning} from '@docusaurus/utils-validation';
import htmlTags from 'html-tags';
import voidHtmlTags from 'html-tags/void';
import escapeHTML from 'escape-html';
import type {FutureConfig, StorageConfig} from '@docusaurus/types/src/config';
import type {
  RouteConfig,
  ReportingSeverity,
  DocusaurusConfig,
  I18nConfig,
  MarkdownConfig,
  Module,
  RouteModules,
  ChunkNames,
  RouteChunkNames,
  PluginRouteConfig,
  PluginIdentifier,
  Props,
  HtmlTagObject,
  HtmlTags,
  LoadedPlugin,
} from '@docusaurus/types';

function matchRoutes(routeConfig: RouteConfig[], pathname: string) {
  // @ts-expect-error: React router types RouteConfig with an actual React
  // component, but we load route components with string paths.
  // We don't actually access component here, so it's fine.
  return reactRouterMatchRoutes(routeConfig, pathname);
}

type BrokenLink = {
  link: string;
  resolvedLink: string;
  anchor: boolean;
};

type BrokenLinksMap = {[pathname: string]: BrokenLink[]};

type CollectedLinks = {
  [pathname: string]: {links: string[]; anchors: string[]};
};

type CollectedLinksNormalized = Map<
  string,
  {links: Set<string>; anchors: Set<string>}
>;

type RoutesCode = {
  routesConfig: string;
  routesChunkNames: RouteChunkNames;
  registry: {
    [chunkName: string]: string;
  };
};

type GenerateRouteFilesParams = {
  generatedFilesDir: string;
  routes: PluginRouteConfig[];
  baseUrl: string;
};

type HostPortOptions = {
  host?: string;
  port?: string;
};

type BrokenLinkState = {
  collectedLinks: CollectedLinksNormalized;
  validPathnames: Set<string>;
  remainingRoutes: RouteConfig[];
  routes: RouteConfig[];
  brokenLinks: BrokenLinksMap;
  brokenPaths: BrokenLinksMap;
  brokenAnchors: BrokenLinksMap;
  onBrokenLinks: ReportingSeverity;
  onBrokenAnchors: ReportingSeverity;
};

type ConfigState = {
  defaultI18nConfig: I18nConfig;
  defaultStorageConfig: StorageConfig;
  defaultFutureConfig: FutureConfig;
  defaultMarkdownConfig: MarkdownConfig;
  defaultConfig: Pick<
    DocusaurusConfig,
    | 'i18n'
    | 'future'
    | 'onBrokenLinks'
    | 'onBrokenAnchors'
    | 'onBrokenMarkdownLinks'
    | 'onDuplicateRoutes'
    | 'plugins'
    | 'themes'
    | 'presets'
    | 'headTags'
    | 'stylesheets'
    | 'scripts'
    | 'clientModules'
    | 'customFields'
    | 'themeConfig'
    | 'titleDelimiter'
    | 'noIndex'
    | 'tagline'
    | 'baseUrlIssueBanner'
    | 'staticDirectories'
    | 'markdown'
  >;
  pluginSchema: unknown;
  themeSchema: unknown;
  presetSchema: unknown;
  localeConfigSchema: unknown;
  i18nConfigSchema: unknown;
  storageConfigSchema: unknown;
  futureConfigSchema: unknown;
  siteUrlSchema: unknown;
  configSchema: ReturnType<typeof Joi.object>;
  siteConfigPath: string;
  lastValidatedConfig: DocusaurusConfig | null;
  unknownFields: string;
  formattedError: string;
};

type HostPortState = {
  host: string;
  port: number | null;
  defaultPort: number;
  existingProcess: string | null;
  execOptions: ExecSyncOptionsWithStringEncoding;
};

type CodegenState = {
  chunkNameCache: Map<string, string>;
  chunkNameCount: Map<string, number>;
  routesCode: RoutesCode;
  generatedFilesDir: string;
  routes: PluginRouteConfig[];
  baseUrl: string;
};

type RouteSlashState = {
  routesToSort: RouteConfig[];
  baseUrl: string;
  trailingSlashParams: ApplyTrailingSlashParams | null;
};

type HtmlTagState = {
  plugins: LoadedPlugin[];
  headTags: string;
  preBodyTags: string;
  postBodyTags: string;
  lastTag: HtmlTagObject | null;
  lastMarkup: string;
};

class SiteOrchestrator {
  private brokenLinkState: BrokenLinkState = {
    collectedLinks: new Map(),
    validPathnames: new Set(),
    remainingRoutes: [],
    routes: [],
    brokenLinks: {},
    brokenPaths: {},
    brokenAnchors: {},
    onBrokenLinks: 'throw',
    onBrokenAnchors: 'warn',
  };

  private configState: ConfigState = {
    defaultI18nConfig: {
      defaultLocale: 'en',
      path: DEFAULT_I18N_DIR_NAME,
      locales: ['en'],
      localeConfigs: {},
    },
    defaultStorageConfig: {
      type: 'localStorage',
      namespace: false,
    },
    defaultFutureConfig: {
      experimental_storage: {
        type: 'localStorage',
        namespace: false,
      },
    },
    defaultMarkdownConfig: {
      format: 'mdx',
      mermaid: false,
      preprocessor: undefined,
      parseFrontMatter: DEFAULT_PARSE_FRONT_MATTER,
      mdx1Compat: {
        comments: true,
        admonitions: true,
        headingIds: true,
      },
      anchors: {
        maintainCase: false,
      },
      remarkRehypeOptions: undefined,
    },
    defaultConfig: {
      i18n: {
        defaultLocale: 'en',
        path: DEFAULT_I18N_DIR_NAME,
        locales: ['en'],
        localeConfigs: {},
      },
      future: {
        experimental_storage: {
          type: 'localStorage',
          namespace: false,
        },
      },
      onBrokenLinks: 'throw',
      onBrokenAnchors: 'warn',
      onBrokenMarkdownLinks: 'warn',
      onDuplicateRoutes: 'warn',
      plugins: [],
      themes: [],
      presets: [],
      headTags: [],
      stylesheets: [],
      scripts: [],
      clientModules: [],
      customFields: {},
      themeConfig: {},
      titleDelimiter: '|',
      noIndex: false,
      tagline: '',
      baseUrlIssueBanner: true,
      staticDirectories: [DEFAULT_STATIC_DIR_NAME],
      markdown: {
        format: 'mdx',
        mermaid: false,
        preprocessor: undefined,
        parseFrontMatter: DEFAULT_PARSE_FRONT_MATTER,
        mdx1Compat: {
          comments: true,
          admonitions: true,
          headingIds: true,
        },
        anchors: {
          maintainCase: false,
        },
        remarkRehypeOptions: undefined,
      },
    },
    pluginSchema: undefined,
    themeSchema: undefined,
    presetSchema: undefined,
    localeConfigSchema: undefined,
    i18nConfigSchema: undefined,
    storageConfigSchema: undefined,
    futureConfigSchema: undefined,
    siteUrlSchema: undefined,
    configSchema: Joi.object(),
    siteConfigPath: '',
    lastValidatedConfig: null,
    unknownFields: '',
    formattedError: '',
  };

  private hostPortState: HostPortState = {
    host: 'localhost',
    port: null,
    defaultPort: DEFAULT_PORT,
    existingProcess: null,
    execOptions: {
      encoding: 'utf8',
      stdio: [/* stdin */ 'pipe', /* stdout */ 'pipe', /* stderr */ 'ignore'],
    },
  };

  private codegenState: CodegenState = {
    chunkNameCache: new Map(),
    chunkNameCount: new Map(),
    routesCode: {
      routesConfig: '',
      routesChunkNames: {},
      registry: {},
    },
    generatedFilesDir: '',
    routes: [],
    baseUrl: '/',
  };

  private routeSlashState: RouteSlashState = {
    routesToSort: [],
    baseUrl: '/',
    trailingSlashParams: null,
  };

  private htmlTagState: HtmlTagState = {
    plugins: [],
    headTags: '',
    preBodyTags: '',
    postBodyTags: '',
    lastTag: null,
    lastMarkup: '',
  };

  private schemasInitialized = this.buildAllConfigSchemas();

  get defaultI18nConfig(): I18nConfig {
    return this.configState.defaultI18nConfig;
  }

  get defaultStorageConfig(): StorageConfig {
    return this.configState.defaultStorageConfig;
  }

  get defaultFutureConfig(): FutureConfig {
    return this.configState.defaultFutureConfig;
  }

  get defaultMarkdownConfig(): MarkdownConfig {
    return this.configState.defaultMarkdownConfig;
  }

  get defaultConfig(): ConfigState['defaultConfig'] {
    return this.configState.defaultConfig;
  }

  get configSchema(): ConfigState['configSchema'] {
    return this.configState.configSchema;
  }

  brokenLinkMessage(brokenLink: BrokenLink): string {
    const showResolvedLink = brokenLink.link !== brokenLink.resolvedLink;
    return `${brokenLink.link}${
      showResolvedLink ? ` (resolved as: ${brokenLink.resolvedLink})` : ''
    }`;
  }

  indent(str: string): string {
    return `  ${str.replace(/\n/g, `\n  `)}`;
  }

  isModule(value: unknown): value is Module {
    return (
      typeof value === 'string' ||
      (typeof value === 'object' &&
        // eslint-disable-next-line no-underscore-dangle
        !!(value as {[key: string]: unknown} | null)?.__import)
    );
  }

  getModulePath(target: Module): string {
    if (typeof target === 'string') {
      return target;
    }
    const queryStr = target.query ? `?${query.stringify(target.query)}` : '';
    return `${target.path}${queryStr}`;
  }

  serializeRouteConfig({
    routePath,
    routeHash,
    exact,
    subroutesCodeStrings,
    attributes,
  }: {
    routePath: string;
    routeHash: string;
    exact?: boolean;
    subroutesCodeStrings?: string[];
    attributes: {[attributeName: string]: unknown};
  }): string {
    const parts = [
      `path: '${routePath}'`,
      `component: ComponentCreator('${routePath}', '${routeHash}')`,
    ];

    if (exact) {
      parts.push(`exact: true`);
    }

    if (subroutesCodeStrings) {
      parts.push(
        `routes: [
${this.indent(subroutesCodeStrings.join(',\n'))}
]`,
      );
    }

    Object.entries(attributes).forEach(([attrName, attrValue]) => {
      const isIdentifier =
        /^[$_\p{ID_Start}][$\u200c\u200d\p{ID_Continue}]*$/u.test(attrName);
      const key = isIdentifier ? attrName : JSON.stringify(attrName);
      parts.push(`${key}: ${JSON.stringify(attrValue)}`);
    });

    return `{
${this.indent(parts.join(',\n'))}
}`;
  }

  ensureNoPropsConflict(route: RouteConfig): void {
    if (!route.props && !route.modules) {
      return;
    }
    const conflictingPropNames = _.intersection(
      Object.keys(route.props ?? {}),
      Object.keys(route.modules ?? {}),
    );
    if (conflictingPropNames.length > 0) {
      throw new Error(
        `Route ${
          route.path
        } has conflicting props declared using both route.modules and route.props APIs for keys: ${conflictingPropNames.join(
          ', ',
        )}\nThis is not permitted, otherwise one prop would override the over.`,
      );
    }
  }

  clearConsole(): void {
    process.stdout.write(
      process.platform === 'win32' ? '\x1B[2J\x1B[0f' : '\x1B[2J\x1B[3J\x1B[H',
    );
  }

  filterIntermediateRoutes(routesInput: RouteConfig[]): RouteConfig[] {
    const routesWithout404 = routesInput.filter((route) => route.path !== '*');
    const flattened = flattenRoutes(routesWithout404);
    this.brokenLinkState.routes = flattened;
    return flattened;
  }

  normalizeCollectedLinks(
    collectedLinks: CollectedLinks,
  ): CollectedLinksNormalized {
    const result: CollectedLinksNormalized = new Map();
    Object.entries(collectedLinks).forEach(([pathname, pageCollectedData]) => {
      result.set(pathname, {
        links: new Set(pageCollectedData.links.filter(_.isString)),
        anchors: new Set(
          pageCollectedData.anchors
            .filter(_.isString)
            .map((anchor) => (anchor.startsWith('#') ? anchor.slice(1) : anchor)),
        ),
      });
    });
    this.brokenLinkState.collectedLinks = result;
    return result;
  }

  prepareBrokenLinkState({
    collectedLinks,
    routes,
  }: {
    collectedLinks: CollectedLinksNormalized;
    routes: RouteConfig[];
  }): void {
    this.brokenLinkState.collectedLinks = collectedLinks;
    this.brokenLinkState.routes = routes;
    this.brokenLinkState.validPathnames = new Set(collectedLinks.keys());

    const disableOptimization = false;
    if (disableOptimization) {
      this.brokenLinkState.remainingRoutes = routes;
      return;
    }
    const [validPathnameRoutes, otherRoutes] = _.partition(
      routes,
      (route) =>
        route.exact && this.brokenLinkState.validPathnames.has(route.path),
    );
    validPathnameRoutes.forEach((validPathnameRoute) => {
      if (!validPathnameRoute.strict) {
        this.brokenLinkState.validPathnames.add(
          addTrailingSlash(validPathnameRoute.path),
        );
        this.brokenLinkState.validPathnames.add(
          removeTrailingSlash(validPathnameRoute.path),
        );
      }
    });
    this.brokenLinkState.remainingRoutes = otherRoutes;
  }

  isPathnameMatchingAnyRoute(pathname: string): boolean {
    if (matchRoutes(this.brokenLinkState.remainingRoutes, pathname).length > 0) {
      this.brokenLinkState.validPathnames.add(pathname);
      return true;
    }
    return false;
  }

  isPathBrokenLink(linkPath: URLPath): boolean {
    const pathnames = [linkPath.pathname, decodeURI(linkPath.pathname)];
    if (pathnames.some((p) => this.brokenLinkState.validPathnames.has(p))) {
      return false;
    }
    if (pathnames.some((p) => this.isPathnameMatchingAnyRoute(p))) {
      return false;
    }
    return true;
  }

  isAnchorBrokenLink(linkPath: URLPath) {
    const collectedLinks = this.brokenLinkState.collectedLinks;
    const {pathname, hash} = linkPath;
    // Link has no hash: it can't be a broken anchor link
    if (hash === undefined) {
      return false;
    }
    // Link has empty hash ("#", "/page#"...): we do not report it as broken
    // Empty hashes are used for various weird reasons, by us and other users...
    // See for example: https://github.com/facebook/docusaurus/pull/6003
    if (hash === '') {
      return false;
    }
    const targetPage =
      collectedLinks.get(pathname) || collectedLinks.get(decodeURI(pathname));
    // link with anchor to a page that does not exist (or did not collect any
    // link/anchor) is considered as a broken anchor
    if (!targetPage) {
      return true;
    }
    // it's a not broken anchor if the anchor exists on the target page
    if (
      targetPage.anchors.has(hash) ||
      targetPage.anchors.has(decodeURIComponent(hash))
    ) {
      return false;
    }
    return true;
  }

  getBrokenLinksForPage(pagePath: string): BrokenLink[] {
    const pageData = this.brokenLinkState.collectedLinks.get(pagePath)!;
    const brokenLinks: BrokenLink[] = [];

    pageData.links.forEach((link) => {
      const linkPath = parseURLPath(link, pagePath);
      if (this.isPathBrokenLink(linkPath)) {
        brokenLinks.push({
          link,
          resolvedLink: serializeURLPath(linkPath),
          anchor: false,
        });
      } else if (this.isAnchorBrokenLink(linkPath)) {
        brokenLinks.push({
          link,
          resolvedLink: serializeURLPath(linkPath),
          anchor: true,
        });
      }
    });

    return brokenLinks;
  }

  collectBrokenLinks(): BrokenLinksMap {
    const result: BrokenLinksMap = {};
    this.brokenLinkState.collectedLinks.forEach((_unused, pagePath) => {
      try {
        result[pagePath] = this.getBrokenLinksForPage(pagePath);
      } catch (e) {
        throw new Error(`Unable to get broken links for page ${pagePath}.`, {
          cause: e,
        });
      }
    });
    this.brokenLinkState.brokenLinks = result;
    return result;
  }

  createBrokenLinksMessage(
    pagePath: string,
    brokenLinks: BrokenLink[],
  ): string {
    const linksForPage =
      brokenLinks.length > 0
        ? brokenLinks
        : this.brokenLinkState.brokenLinks[pagePath] ?? [];
    const type = linksForPage[0]?.anchor === true ? 'anchor' : 'link';
    const anchorMessage =
      linksForPage.length > 0
        ? `- Broken ${type} on source page path = ${pagePath}:
   -> linking to ${linksForPage
     .map((item) => this.brokenLinkMessage(item))
     .join('\n   -> linking to ')}`
        : '';
    return `${anchorMessage}`;
  }

  getFrequentBrokenLinksMessage(brokenPathsMap: BrokenLinksMap): string {
    const sourceMap =
      Object.keys(brokenPathsMap).length > 0
        ? brokenPathsMap
        : this.brokenLinkState.brokenPaths;
    const flatList = Object.entries(sourceMap).flatMap(
      ([pagePath, brokenLinks]) =>
        brokenLinks.map((brokenLink) => ({pagePath, brokenLink})),
    );

    const countedBrokenLinks = _.countBy(
      flatList,
      (item) => item.brokenLink.link,
    );

    const FrequencyThreshold = 5;
    const frequentLinks = Object.entries(countedBrokenLinks)
      .filter(([, count]) => count >= FrequencyThreshold)
      .map(([link]) => link);

    if (frequentLinks.length === 0) {
      return '';
    }

    return logger.interpolate`

It looks like some of the broken links we found appear in many pages of your site.
Maybe those broken links appear on all pages through your site layout?
We recommend that you check your theme configuration for such links (particularly, theme navbar and footer).
Frequent broken links are linking to:${frequentLinks}`;
  }

  createBrokenAnchorsMessage(brokenAnchors: BrokenLinksMap): string | undefined {
    const anchorsToReport =
      Object.keys(brokenAnchors).length > 0
        ? brokenAnchors
        : this.brokenLinkState.brokenAnchors;
    if (Object.keys(anchorsToReport).length === 0) {
      return undefined;
    }

    return `Docusaurus found broken anchors!

Please check the pages of your site in the list below, and make sure you don't reference any anchor that does not exist.
Note: it's possible to ignore broken anchors with the 'onBrokenAnchors' Docusaurus configuration, and let the build pass.

Exhaustive list of all broken anchors found:
${Object.entries(anchorsToReport)
  .map(([pagePath, brokenAnchorsForPage]) =>
    this.createBrokenLinksMessage(pagePath, brokenAnchorsForPage),
  )
  .join('\n')}
`;
  }

  createBrokenPathsMessage(brokenPathsMap: BrokenLinksMap): string | undefined {
    const pathsToReport =
      Object.keys(brokenPathsMap).length > 0
        ? brokenPathsMap
        : this.brokenLinkState.brokenPaths;
    if (Object.keys(pathsToReport).length === 0) {
      return undefined;
    }

    return `Docusaurus found broken links!

Please check the pages of your site in the list below, and make sure you don't reference any path that does not exist.
Note: it's possible to ignore broken links with the 'onBrokenLinks' Docusaurus configuration, and let the build pass.${this.getFrequentBrokenLinksMessage(
      pathsToReport,
    )}

Exhaustive list of all broken links found:
${Object.entries(pathsToReport)
  .map(([pagePath, brokenPaths]) =>
    this.createBrokenLinksMessage(pagePath, brokenPaths),
  )
  .join('\n')}
`;
  }

  splitBrokenLinks(): {brokenPaths: BrokenLinksMap; brokenAnchors: BrokenLinksMap} {
    const brokenPaths: BrokenLinksMap = {};
    const brokenAnchors: BrokenLinksMap = {};

    Object.entries(this.brokenLinkState.brokenLinks).forEach(
      ([pathname, pageBrokenLinks]) => {
        const [anchorBrokenLinks, pathBrokenLinks] = _.partition(
          pageBrokenLinks,
          (link) => link.anchor,
        );

        if (pathBrokenLinks.length > 0) {
          brokenPaths[pathname] = pathBrokenLinks;
        }
        if (anchorBrokenLinks.length > 0) {
          brokenAnchors[pathname] = anchorBrokenLinks;
        }
      },
    );

    this.brokenLinkState.brokenPaths = brokenPaths;
    this.brokenLinkState.brokenAnchors = brokenAnchors;
    return {brokenPaths, brokenAnchors};
  }

  reportBrokenLinks(): void {
    const {brokenPaths, brokenAnchors} = this.splitBrokenLinks();

    const pathErrorMessage = this.createBrokenPathsMessage(brokenPaths);
    if (pathErrorMessage) {
      logger.report(this.brokenLinkState.onBrokenLinks)(pathErrorMessage);
    }

    const anchorErrorMessage = this.createBrokenAnchorsMessage(brokenAnchors);
    if (anchorErrorMessage) {
      logger.report(this.brokenLinkState.onBrokenAnchors)(anchorErrorMessage);
    }
  }

  async handleBrokenLinks({
    collectedLinks,
    onBrokenLinks,
    onBrokenAnchors,
    routes,
  }: {
    collectedLinks: CollectedLinks;
    onBrokenLinks: ReportingSeverity;
    onBrokenAnchors: ReportingSeverity;
    routes: RouteConfig[];
  }): Promise<void> {
    this.brokenLinkState.onBrokenLinks = onBrokenLinks;
    this.brokenLinkState.onBrokenAnchors = onBrokenAnchors;
    if (onBrokenLinks === 'ignore' && onBrokenAnchors === 'ignore') {
      return;
    }
    const normalized = this.normalizeCollectedLinks(collectedLinks);
    const filteredRoutes = this.filterIntermediateRoutes(routes);
    this.prepareBrokenLinkState({
      collectedLinks: normalized,
      routes: filteredRoutes,
    });
    this.collectBrokenLinks();
    this.reportBrokenLinks();
  }

  createPluginSchema(theme: boolean): unknown {
    const schema = Joi.alternatives()
      .try(
        Joi.function(),
        Joi.array()
          .ordered(Joi.function().required(), Joi.object().required())
          .length(2),
        Joi.string(),
        Joi.array()
          .ordered(Joi.string().required(), Joi.object().required())
          .length(2),
        Joi.any().valid(false, null),
      )
      // @ts-expect-error: bad lib def, doesn't recognize an array of reports
      .error((errors) => {
        errors.forEach((error) => {
          const validConfigExample = theme
            ? `Example valid theme config:
{
  themes: [
    ["@docusaurus/theme-classic",options],
    "./myTheme",
    ["./myTheme",{someOption: 42}],
    function myTheme() { },
    [function myTheme() { },options]
  ],
};`
            : `Example valid plugin config:
{
  plugins: [
    ["@docusaurus/plugin-content-docs",options],
    "./myPlugin",
    ["./myPlugin",{someOption: 42}],
    function myPlugin() { },
    [function myPlugin() { },options]
  ],
};`;

          error.message = ` => Bad Docusaurus ${
            theme ? 'theme' : 'plugin'
          } value ${error.path.reduce((acc, cur) =>
            typeof cur === 'string' ? `${acc}.${cur}` : `${acc}[${cur}]`,
          )}.
${validConfigExample}
`;
        });
        return errors;
      });
    if (theme) {
      this.configState.themeSchema = schema;
    } else {
      this.configState.pluginSchema = schema;
    }
    return schema;
  }

  createThemeSchema(): unknown {
    const schema = this.createPluginSchema(true);
    this.configState.themeSchema = schema;
    return schema;
  }

  createPresetSchema(): unknown {
    const schema = Joi.alternatives()
      .try(
        Joi.string(),
        Joi.array()
          .items(Joi.string().required(), Joi.object().required())
          .length(2),
        Joi.any().valid(false, null),
      )
      .messages({
        'alternatives.types': `{#label} does not look like a valid preset config. A preset config entry should be one of:
- A tuple of [presetName, options], like \`["classic", \\{ blog: false \\}]\`, or
- A simple string, like \`"classic"\``,
      });
    this.configState.presetSchema = schema;
    return schema;
  }

  buildLocaleConfigSchema(): unknown {
    const schema = Joi.object({
      label: Joi.string(),
      htmlLang: Joi.string(),
      direction: Joi.string().equal('ltr', 'rtl').default('ltr'),
      calendar: Joi.string(),
      path: Joi.string(),
    });
    this.configState.localeConfigSchema = schema;
    return schema;
  }

  buildI18nConfigSchema(): unknown {
    const schema = Joi.object<I18nConfig>({
      defaultLocale: Joi.string().required(),
      path: Joi.string().default(this.configState.defaultI18nConfig.path),
      locales: Joi.array()
        .items()
        .min(1)
        .items(Joi.string().required())
        .required(),
      localeConfigs: Joi.object()
        .pattern(/.*/, this.buildLocaleConfigSchema())
        .default(this.configState.defaultI18nConfig.localeConfigs),
    })
      .optional()
      .default(this.configState.defaultI18nConfig);
    this.configState.i18nConfigSchema = schema;
    return schema;
  }

  buildStorageConfigSchema(): unknown {
    const schema = Joi.object({
      type: Joi.string()
        .equal('localStorage', 'sessionStorage')
        .default(this.configState.defaultStorageConfig.type),
      namespace: Joi.alternatives()
        .try(Joi.string(), Joi.boolean())
        .default(this.configState.defaultStorageConfig.namespace),
    })
      .optional()
      .default(this.configState.defaultStorageConfig);
    this.configState.storageConfigSchema = schema;
    return schema;
  }

  buildFutureConfigSchema(): unknown {
    const schema = Joi.object<FutureConfig>({
      experimental_storage: this.buildStorageConfigSchema(),
    })
      .optional()
      .default(this.configState.defaultFutureConfig);
    this.configState.futureConfigSchema = schema;
    return schema;
  }

  buildSiteUrlSchema(): unknown {
    const schema = Joi.string()
      .required()
      .custom((value: string, helpers) => {
        try {
          const {pathname} = new URL(value);
          if (pathname !== '/') {
            return helpers.error('docusaurus.subPathError', {pathname});
          }
        } catch {
          return helpers.error('any.invalid');
        }
        return removeTrailingSlash(value);
      })
      .messages({
        'any.invalid':
          '"{#value}" does not look like a valid URL. Make sure it has a protocol; for example, "https://example.com".',
        'docusaurus.subPathError':
          'The url is not supposed to contain a sub-path like "{#pathname}". Please use the baseUrl field for sub-paths.',
      });
    this.configState.siteUrlSchema = schema;
    return schema;
  }

  buildConfigSchema(): ReturnType<typeof Joi.object> {
    const defaults = this.configState.defaultConfig;
    const schema = Joi.object<DocusaurusConfig>({
      baseUrl: Joi.alternatives()
        .try(Joi.string().required().allow(''))
        .required()
        .custom((value: string) => addLeadingSlash(addTrailingSlash(value))),
      baseUrlIssueBanner: Joi.boolean().default(defaults.baseUrlIssueBanner),
      favicon: Joi.string().optional(),
      title: Joi.string().required(),
      url: this.buildSiteUrlSchema(),
      trailingSlash: Joi.boolean(),
      i18n: this.buildI18nConfigSchema(),
      future: this.buildFutureConfigSchema(),
      onBrokenLinks: Joi.string()
        .equal('ignore', 'log', 'warn', 'throw')
        .default(defaults.onBrokenLinks),
      onBrokenAnchors: Joi.string()
        .equal('ignore', 'log', 'warn', 'throw')
        .default(defaults.onBrokenAnchors),
      onBrokenMarkdownLinks: Joi.string()
        .equal('ignore', 'log', 'warn', 'throw')
        .default(defaults.onBrokenMarkdownLinks),
      onDuplicateRoutes: Joi.string()
        .equal('ignore', 'log', 'warn', 'throw')
        .default(defaults.onDuplicateRoutes),
      organizationName: Joi.string().allow(''),
      staticDirectories: Joi.array()
        .items(Joi.string())
        .default(defaults.staticDirectories),
      projectName: Joi.string().allow(''),
      deploymentBranch: Joi.string().optional(),
      customFields: Joi.object().unknown().default(defaults.customFields),
      githubHost: Joi.string(),
      githubPort: Joi.string(),
      plugins: Joi.array()
        .items(this.createPluginSchema(false))
        .default(defaults.plugins),
      themes: Joi.array()
        .items(this.createThemeSchema())
        .default(defaults.themes),
      presets: Joi.array()
        .items(this.createPresetSchema())
        .default(defaults.presets),
      themeConfig: Joi.object().unknown().default(defaults.themeConfig),
      scripts: Joi.array()
        .items(
          Joi.string(),
          Joi.object({
            src: Joi.string().required(),
            async: Joi.bool(),
            defer: Joi.bool(),
          }).unknown(),
        )
        .messages({
          'array.includes':
            '{#label} is invalid. A script must be a plain string (the src), or an object with at least a "src" property.',
        })
        .default(defaults.scripts),
      ssrTemplate: Joi.string(),
      headTags: Joi.array()
        .items(
          Joi.object({
            tagName: Joi.string().required(),
            attributes: Joi.object()
              .pattern(/[\w-]+/, Joi.string())
              .required(),
          }).unknown(),
        )
        .messages({
          'array.includes':
            '{#label} is invalid. A headTag must be an object with at least a "tagName" and an "attributes" property.',
        })
        .default(defaults.headTags),
      stylesheets: Joi.array()
        .items(
          Joi.string(),
          Joi.object({
            href: Joi.string().required(),
            type: Joi.string(),
          }).unknown(),
        )
        .messages({
          'array.includes':
            '{#label} is invalid. A stylesheet must be a plain string (the href), or an object with at least a "href" property.',
        })
        .default(defaults.stylesheets),
      clientModules: Joi.array().items(Joi.string()).default(defaults.clientModules),
      tagline: Joi.string().allow('').default(defaults.tagline),
      titleDelimiter: Joi.string().default(defaults.titleDelimiter),
      noIndex: Joi.bool().default(defaults.noIndex),
      webpack: Joi.object({
        jsLoader: Joi.alternatives()
          .try(Joi.string().equal('babel'), Joi.function())
          .optional(),
      }).optional(),
      markdown: Joi.object({
        format: Joi.string()
          .equal('mdx', 'md', 'detect')
          .default(defaults.markdown.format),
        parseFrontMatter: Joi.function().default(
          () => defaults.markdown.parseFrontMatter,
        ),
        mermaid: Joi.boolean().default(defaults.markdown.mermaid),
        preprocessor: Joi.function()
          .arity(1)
          .optional()
          .default(() => defaults.markdown.preprocessor),
        mdx1Compat: Joi.object({
          comments: Joi.boolean().default(defaults.markdown.mdx1Compat.comments),
          admonitions: Joi.boolean().default(
            defaults.markdown.mdx1Compat.admonitions,
          ),
          headingIds: Joi.boolean().default(
            defaults.markdown.mdx1Compat.headingIds,
          ),
        }).default(defaults.markdown.mdx1Compat),
        remarkRehypeOptions: Joi.object().unknown(),
        anchors: Joi.object({
          maintainCase: Joi.boolean().default(
            defaults.markdown.anchors.maintainCase,
          ),
        }).default(defaults.markdown.anchors),
      }).default(defaults.markdown),
    }).messages({
      'docusaurus.configValidationWarning':
        'Docusaurus config validation warning. Field {#label}: {#warningMessage}',
    });
    this.configState.configSchema = schema;
    return schema;
  }

  linkConfigDefaultReferences(): void {
    this.configState.defaultFutureConfig.experimental_storage =
      this.configState.defaultStorageConfig;
    this.configState.defaultConfig.i18n = this.configState.defaultI18nConfig;
    this.configState.defaultConfig.future = this.configState.defaultFutureConfig;
    this.configState.defaultConfig.markdown = this.configState.defaultMarkdownConfig;
  }

  buildAllConfigSchemas(): boolean {
    this.linkConfigDefaultReferences();
    this.buildConfigSchema();
    return this.configState.configSchema !== undefined;
  }

  collectUnknownConfigFields(error: {details: {type: string; path: Array<string | number>}[]}): string {
    this.configState.unknownFields = error.details.reduce((formattedError, err) => {
      if (err.type === 'object.unknown') {
        return `${formattedError}"${err.path.reduce((acc, cur) =>
          typeof cur === 'string' ? `${acc}.${cur}` : `${acc}[${cur}]`,
        )}",`;
      }
      return formattedError;
    }, '');
    return this.configState.unknownFields;
  }

  formatConfigValidationError(error: {
    details: {type: string; message: string; path: Array<string | number>}[];
  }): string {
    const unknownFields = this.collectUnknownConfigFields(error);
    let formattedError = error.details.reduce(
      (accumulatedErr, err) =>
        err.type !== 'object.unknown'
          ? `${accumulatedErr}${err.message}\n`
          : accumulatedErr,
      '',
    );
    formattedError = unknownFields
      ? `${formattedError}These field(s) (${unknownFields}) are not recognized in ${this.configState.siteConfigPath}.\nIf you still want these fields to be in your configuration, put them in the "customFields" field.\nSee https://docusaurus.io/docs/api/docusaurus-config/#customfields`
      : formattedError;
    this.configState.formattedError = formattedError;
    return formattedError;
  }

  validateConfig(config: unknown, siteConfigPath: string): DocusaurusConfig {
    this.configState.siteConfigPath = siteConfigPath;
    const {error, warning, value} = this.configState.configSchema.validate(
      config,
      {
        abortEarly: false,
      },
    );

    printWarning(warning);

    if (error) {
      throw new Error(this.formatConfigValidationError(error));
    }
    this.configState.lastValidatedConfig = value;
    return value;
  }

  getProcessForPort(port: number): string | null {
    this.hostPortState.port = port;
    try {
      const processId = execSync(
        `lsof -i:${port} -P -t -sTCP:LISTEN`,
        this.hostPortState.execOptions,
      )
        .split('\n')[0]!
        .trim();
      const directory = execSync(
        `lsof -p ${processId} | awk '$4=="cwd" {for (i=9; i<=NF; i++) printf "%s ", $i}'`,
        this.hostPortState.execOptions,
      ).trim();
      const command = execSync(
        `ps -o command -p ${processId} | sed -n 2p`,
        this.hostPortState.execOptions,
      ).replace(/\n$/, '');
      this.hostPortState.existingProcess = logger.interpolate`code=${command} subdue=${`(pid ${processId})`} in path=${directory}`;
      return this.hostPortState.existingProcess;
    } catch {
      this.hostPortState.existingProcess = null;
      return null;
    }
  }

  async choosePort(host: string, defaultPort: number): Promise<number | null> {
    this.hostPortState.host = host;
    this.hostPortState.defaultPort = defaultPort;
    try {
      const port = await detect({
        port: defaultPort,
        ...(host !== 'localhost' && {hostname: host}),
      });
      if (port === defaultPort) {
        this.hostPortState.port = port;
        return port;
      }
      const isRoot = process.getuid?.() === 0;
      const isInteractive = process.stdout.isTTY;
      const message =
        process.platform !== 'win32' && defaultPort < 1024 && !isRoot
          ? `Admin permissions are required to run a server on a port below 1024.`
          : `Something is already running on port ${defaultPort}.`;
      if (!isInteractive) {
        logger.error(message);
        this.hostPortState.port = null;
        return null;
      }
      this.clearConsole();
      const existingProcess = this.getProcessForPort(defaultPort);
      const {shouldChangePort} = (await prompts({
        type: 'confirm',
        name: 'shouldChangePort',
        message: logger.yellow(`${logger.bold('[WARNING]')} ${message}${
          existingProcess ? ` Probably:\n  ${existingProcess}` : ''
        }

Would you like to run the app on another port instead?`),
        initial: true,
      })) as {shouldChangePort: boolean};
      this.hostPortState.port = shouldChangePort ? port : null;
      return this.hostPortState.port;
    } catch (err) {
      logger.error`Could not find an open port at ${host}.`;
      throw err;
    }
  }

  async getHostPort(options: HostPortOptions): Promise<{
    host: string;
    port: number | null;
  }> {
    this.hostPortState.host = options.host ?? 'localhost';
    this.hostPortState.defaultPort = options.port
      ? parseInt(options.port, 10)
      : DEFAULT_PORT;
    this.hostPortState.port = await this.choosePort(
      this.hostPortState.host,
      this.hostPortState.defaultPort,
    );
    return {host: this.hostPortState.host, port: this.hostPortState.port};
  }

  genChunkName(
    modulePath: string,
    prefix?: string,
    preferredName?: string,
    shortId: boolean = process.env.NODE_ENV === 'production',
  ): string {
    let chunkName = this.codegenState.chunkNameCache.get(modulePath);
    if (!chunkName) {
      if (shortId) {
        chunkName = simpleHash(modulePath, 8);
      } else {
        let str = modulePath;
        if (preferredName) {
          const shortHash = simpleHash(modulePath, 3);
          str = `${preferredName}${shortHash}`;
        }
        const name = docuHash(str);
        chunkName = prefix ? `${prefix}---${name}` : name;
      }
      const seenCount =
        (this.codegenState.chunkNameCount.get(chunkName) ?? 0) + 1;
      if (seenCount > 1) {
        chunkName += seenCount.toString(36);
      }
      this.codegenState.chunkNameCache.set(modulePath, chunkName);
      this.codegenState.chunkNameCount.set(chunkName, seenCount);
    }
    return chunkName;
  }

  genChunkNames(
    routeModule: RouteModules,
    prefix: string,
    name: string,
    res: RoutesCode,
  ): ChunkNames;
  genChunkNames(
    routeModule: RouteModules | RouteModules[] | Module,
    prefix: string,
    name: string,
    res: RoutesCode,
  ): ChunkNames | ChunkNames[] | string;
  genChunkNames(
    routeModule: RouteModules | RouteModules[] | Module,
    prefix: string,
    name: string,
    res: RoutesCode,
  ): string | ChunkNames | ChunkNames[] {
    this.codegenState.routesCode = res;
    if (this.isModule(routeModule)) {
      const modulePath = this.getModulePath(routeModule);
      const chunkName = this.genChunkName(modulePath, prefix, name);
      res.registry[chunkName] = escapePath(modulePath);
      return chunkName;
    }
    if (Array.isArray(routeModule)) {
      return routeModule.map((val, index) =>
        this.genChunkNames(val, `${index}`, name, res),
      );
    }
    return _.mapValues(routeModule, (v, key) =>
      this.genChunkNames(v, key, name, res),
    );
  }

  genRouteCode(routeConfig: RouteConfig, res: RoutesCode): string {
    this.codegenState.routesCode = res;
    const {
      path: routePath,
      component,
      modules = {},
      context,
      routes: subroutes,
      priority,
      exact,
      metadata,
      props,
      plugin,
      ...attributes
    } = routeConfig;

    if (typeof routePath !== 'string' || !component) {
      throw new Error(
        `Invalid route config: path must be a string and component is required.
${JSON.stringify(routeConfig)}`,
      );
    }

    const routeHash = simpleHash(JSON.stringify(routeConfig), 3);
    res.routesChunkNames[`${routePath}-${routeHash}`] = {
      ...this.genChunkNames({__comp: component}, 'component', component, res),
      ...(context &&
        this.genChunkNames({__context: context}, 'context', routePath, res)),
      ...this.genChunkNames(modules, 'module', routePath, res),
    };

    return this.serializeRouteConfig({
      routePath: routePath.replace(/'/g, "\\'"),
      routeHash,
      subroutesCodeStrings: subroutes?.map((r) => this.genRouteCode(r, res)),
      exact,
      attributes,
    });
  }

  generateRoutesCode(routeConfigs: RouteConfig[]): RoutesCode {
    const res: RoutesCode = {
      routesConfig: '',
      routesChunkNames: {},
      registry: {},
    };
    this.codegenState.routesCode = res;

    const routeConfigSerialized = routeConfigs
      .map((r) => this.genRouteCode(r, res))
      .join(',\n');

    res.routesConfig = `import React from 'react';
import ComponentCreator from '@docusaurus/ComponentCreator';

export default [
${this.indent(routeConfigSerialized)},
  {
    path: '*',
    component: ComponentCreator('*'),
  },
];
`;
    this.codegenState.routesCode = res;
    return res;
  }

  genRegistry({
    generatedFilesDir,
    registry,
  }: {
    generatedFilesDir: string;
    registry: RoutesCode['registry'];
  }) {
    this.codegenState.generatedFilesDir = generatedFilesDir;
    this.codegenState.routesCode.registry = registry;
    return generate(
      generatedFilesDir,
      'registry.js',
      `export default {
${Object.entries(registry)
  .sort((a, b) => a[0].localeCompare(b[0]))
  .map(
    ([chunkName, modulePath]) =>
      `  "${chunkName}": [() => import(/* webpackChunkName: "${chunkName}" */ "${modulePath}"), "${modulePath}", require.resolveWeak("${modulePath}")],`,
  )
  .join('\n')}};
`,
    );
  }

  genRoutesChunkNames({
    generatedFilesDir,
    routesChunkNames,
  }: {
    generatedFilesDir: string;
    routesChunkNames: RoutesCode['routesChunkNames'];
  }) {
    this.codegenState.generatedFilesDir = generatedFilesDir;
    this.codegenState.routesCode.routesChunkNames = routesChunkNames;
    return generate(
      generatedFilesDir,
      'routesChunkNames.json',
      JSON.stringify(routesChunkNames, null, 2),
    );
  }

  genRoutes({
    generatedFilesDir,
    routesConfig,
  }: {
    generatedFilesDir: string;
    routesConfig: RoutesCode['routesConfig'];
  }) {
    this.codegenState.generatedFilesDir = generatedFilesDir;
    this.codegenState.routesCode.routesConfig = routesConfig;
    return generate(generatedFilesDir, 'routes.js', routesConfig);
  }

  async generateRoutePropModule({
    generatedFilesDir,
    route,
    plugin,
  }: {
    generatedFilesDir: string;
    route: RouteConfig;
    plugin: PluginIdentifier;
  }) {
    this.codegenState.generatedFilesDir = generatedFilesDir;
    this.ensureNoPropsConflict(route);

    const moduleContent = JSON.stringify(route.props);
    const relativePath = path.posix.join(
      plugin.name,
      plugin.id,
      'p',
      `${docuHash(route.path)}.json`,
    );
    const modulePath = path.posix.join(generatedFilesDir, relativePath);
    const aliasedPath = path.posix.join('@generated', relativePath);

    await generate(generatedFilesDir, modulePath, moduleContent);
    return aliasedPath;
  }

  async preprocessRouteProps({
    generatedFilesDir,
    route,
    plugin,
  }: {
    generatedFilesDir: string;
    route: RouteConfig;
    plugin: PluginIdentifier;
  }): Promise<RouteConfig> {
    this.codegenState.generatedFilesDir = generatedFilesDir;
    const propsModulePathPromise = route.props
      ? this.generateRoutePropModule({
          generatedFilesDir,
          route,
          plugin,
        })
      : undefined;

    const subRoutesPromise = route.routes
      ? Promise.all(
          route.routes.map((subRoute: RouteConfig) => {
            return this.preprocessRouteProps({
              generatedFilesDir,
              route: subRoute,
              plugin,
            });
          }),
        )
      : undefined;

    const [propsModulePath, subRoutes] = await Promise.all([
      propsModulePathPromise,
      subRoutesPromise,
    ]);

    const newRoute: RouteConfig = {
      ...route,
      modules: {
        ...route.modules,
        ...(propsModulePath && {__props: propsModulePath}),
      },
      routes: subRoutes,
      props: undefined,
    };

    return newRoute;
  }

  async preprocessAllPluginsRoutesProps({
    generatedFilesDir,
    routes,
  }: {
    generatedFilesDir: string;
    routes: PluginRouteConfig[];
  }) {
    this.codegenState.generatedFilesDir = generatedFilesDir;
    this.codegenState.routes = routes;
    return Promise.all(
      routes.map((route) => {
        return this.preprocessRouteProps({
          generatedFilesDir,
          route,
          plugin: route.plugin,
        });
      }),
    );
  }

  async generateRouteFiles({
    generatedFilesDir,
    routes: initialRoutes,
  }: GenerateRouteFilesParams): Promise<void> {
    this.codegenState.generatedFilesDir = generatedFilesDir;
    this.codegenState.routes = initialRoutes;
    const routes = await this.preprocessAllPluginsRoutesProps({
      generatedFilesDir,
      routes: initialRoutes,
    });

    const {registry, routesChunkNames, routesConfig} =
      this.generateRoutesCode(routes);
    await Promise.all([
      this.genRegistry({generatedFilesDir, registry}),
      this.genRoutesChunkNames({generatedFilesDir, routesChunkNames}),
      this.genRoutes({generatedFilesDir, routesConfig}),
    ]);
  }

  applyRouteTrailingSlash<Route extends RouteConfig>(
    route: Route,
    params: ApplyTrailingSlashParams,
  ): Route {
    this.routeSlashState.trailingSlashParams = params;
    return {
      ...route,
      path: applyTrailingSlash(route.path, params),
      ...(route.routes && {
        routes: route.routes.map((subroute) =>
          this.applyRouteTrailingSlash(subroute, params),
        ),
      }),
    };
  }

  compareRoutes(a: RouteConfig, b: RouteConfig): number {
    const baseUrl = this.routeSlashState.baseUrl;
    if (a.path === baseUrl && b.path !== baseUrl) {
      return 1;
    }
    if (a.path !== baseUrl && b.path === baseUrl) {
      return -1;
    }

    if (a.routes && !b.routes) {
      return 1;
    }
    if (!a.routes && b.routes) {
      return -1;
    }

    if (a.routes && b.routes) {
      if (a.path === b.path) {
        // overlapping parent routes are currently unsupported
      } else {
        if (a.path.includes(b.path)) {
          return -1;
        }
        if (b.path.includes(a.path)) {
          return 1;
        }
      }
    }

    if (a.priority || b.priority) {
      const priorityA = a.priority ?? 0;
      const priorityB = b.priority ?? 0;
      const score = priorityB - priorityA;
      if (score !== 0) {
        return score;
      }
    }

    return a.path.localeCompare(b.path);
  }

  sortRoutes<Route extends RouteConfig>(
    routesToSort: Route[],
    baseUrl: string,
  ): Route[] {
    this.routeSlashState.baseUrl = baseUrl;
    this.routeSlashState.routesToSort = routesToSort;
    const routeConfigs = [...routesToSort];
    routeConfigs.sort((a, b) => this.compareRoutes(a, b));

    routeConfigs.forEach((routeConfig) => {
      if (routeConfig.routes) {
        routeConfig.routes = this.sortRoutes(routeConfig.routes, baseUrl);
      }
    });

    this.routeSlashState.routesToSort = routeConfigs;
    return routeConfigs;
  }

  assertIsHtmlTagObject(val: unknown): asserts val is HtmlTagObject {
    if (typeof val !== 'object' || !val) {
      throw new Error(`"${val}" is not a valid HTML tag object.`);
    }
    if (typeof (val as HtmlTagObject).tagName !== 'string') {
      throw new Error(
        `${JSON.stringify(
          val,
        )} is not a valid HTML tag object. "tagName" must be defined as a string.`,
      );
    }
    if (!(htmlTags as string[]).includes((val as HtmlTagObject).tagName)) {
      throw new Error(
        `Error loading ${JSON.stringify(val)}, "${
          (val as HtmlTagObject).tagName
        }" is not a valid HTML tag.`,
      );
    }
    this.htmlTagState.lastTag = val as HtmlTagObject;
  }

  htmlTagObjectToString(tag: unknown): string {
    this.assertIsHtmlTagObject(tag);
    const isVoidTag = (voidHtmlTags as string[]).includes(tag.tagName);
    const tagAttributes = tag.attributes ?? {};
    const attributes = Object.keys(tagAttributes)
      .map((attr) => {
        const value = tagAttributes[attr]!;
        if (typeof value === 'boolean') {
          return value ? attr : undefined;
        }
        return `${attr}="${escapeHTML(value)}"`;
      })
      .filter((str): str is string => Boolean(str));
    const openingTag = `<${[tag.tagName].concat(attributes).join(' ')}>`;
    const innerHTML = (!isVoidTag && tag.innerHTML) || '';
    const closingTag = isVoidTag ? '' : `</${tag.tagName}>`;
    const markup = openingTag + innerHTML + closingTag;
    this.htmlTagState.lastMarkup = markup;
    return markup;
  }

  createHtmlTagsString(tags: HtmlTags | undefined): string {
    const markup = (Array.isArray(tags) ? tags : [tags])
      .filter(Boolean)
      .map((val) =>
        typeof val === 'string' ? val : this.htmlTagObjectToString(val),
      )
      .join('\n');
    this.htmlTagState.lastMarkup = markup;
    return markup;
  }

  loadHtmlTags(
    plugins: LoadedPlugin[],
  ): Pick<Props, 'headTags' | 'preBodyTags' | 'postBodyTags'> {
    this.htmlTagState.plugins = plugins;
    const pluginHtmlTags = plugins.map(
      (plugin) => plugin.injectHtmlTags?.({content: plugin.content}) ?? {},
    );
    const tagTypes = ['headTags', 'preBodyTags', 'postBodyTags'] as const;
    const aggregated = Object.fromEntries(
      _.zip(
        tagTypes,
        tagTypes.map((type) =>
          pluginHtmlTags
            .map((tags) => this.createHtmlTagsString(tags[type]))
            .join('\n')
            .trim(),
        ),
      ),
    ) as Pick<Props, 'headTags' | 'preBodyTags' | 'postBodyTags'>;
    this.htmlTagState.headTags = aggregated.headTags;
    this.htmlTagState.preBodyTags = aggregated.preBodyTags;
    this.htmlTagState.postBodyTags = aggregated.postBodyTags;
    return aggregated;
  }
}

const siteOrchestrator = new SiteOrchestrator();

export function getSiteOrchestrator(): SiteOrchestrator {
  return siteOrchestrator;
}

export async function handleBrokenLinks({
  collectedLinks,
  onBrokenLinks,
  onBrokenAnchors,
  routes,
}: {
  collectedLinks: CollectedLinks;
  onBrokenLinks: ReportingSeverity;
  onBrokenAnchors: ReportingSeverity;
  routes: RouteConfig[];
}): Promise<void> {
  const orchestrator = new SiteOrchestrator();
  await orchestrator.handleBrokenLinks({
    collectedLinks,
    onBrokenLinks,
    onBrokenAnchors,
    routes,
  });
}

