        },
      },
    });
  });

  it('accepts valid link with querystring + anchor', async () => {
    await testBrokenLinks({
      routes: [{path: '/page1'}, {path: '/page2'}],
      collectedLinks: {
        '/page1': {
          links: ['/page2?age=42&theme=dark#page2anchor'],
