        '/page2': {links: [], anchors: ['page2anchor']},
      },
    });
  });

  it('accepts valid link to self', async () => {
    await testBrokenLinks({
      routes: [{path: '/page1'}],
      collectedLinks: {
        '/page1': {
          links: [
            '/page1',
